package com.hyperosa5pro;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends Activity{
 int bg,fg,muted,card,accent;LinearLayout root;boolean drawer=false;EditText search;
 int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
 TextView tx(String s,int z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void colors(){boolean d=ThemeStore.dark(this);bg=d?0xFF0D0F13:0xFFF4F5F9;fg=d?0xFFF8F8FA:0xFF171923;muted=d?0xFFB6BAC5:0xFF777D8A;card=d?0xFF202229:Color.WHITE;accent=ThemeStore.get(this,"accent",0xFF5478F5);}
 void base(){colors();root=col();root.setBackgroundColor(bg);setContentView(root);}
 @Override public void onCreate(Bundle b){super.onCreate(b);home();}
 @Override protected void onResume(){super.onResume();if(root!=null)home();}
 TextView chip(String s,Runnable r){TextView t=tx(s,13,fg,true);t.setGravity(17);t.setPadding(dp(15),dp(12),dp(15),dp(12));t.setBackground(shape(card,24));t.setOnClickListener(v->r.run());return t;}
 void home(){drawer=false;base();
 LinearLayout top=row();top.setPadding(dp(22),dp(15),dp(22),dp(5));top.addView(tx("●  "+new SimpleDateFormat("EEE, d MMM",Locale.getDefault()).format(new Date()),14,muted,true),new LinearLayout.LayoutParams(0,-2,1));TextView gear=tx("⚙",24,fg,false);gear.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));top.addView(gear);root.addView(top);
 LinearLayout hero=col();hero.setPadding(dp(23),dp(18),dp(23),dp(17));TextView time=tx(new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),68,fg,false);time.setLetterSpacing(-.045f);hero.addView(time);hero.addView(tx(new SimpleDateFormat("EEEE, d 'de' MMMM",new Locale("es","ES")).format(new Date()),15,muted,false));root.addView(hero);
 LinearLayout widget=row();widget.setPadding(dp(19),dp(18),dp(19),dp(18));widget.setBackground(shape(0xFF9DB2FF,27));LinearLayout w=col();w.addView(tx("Un buen día empieza aquí",17,0xFF17234D,true));w.addView(tx("Todo a tu manera",13,0xFF273B78,false));widget.addView(w,new LinearLayout.LayoutParams(0,-2,1));widget.addView(tx("☀",38,0xFFFFF1C7,false));LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(-1,-2);wp.setMargins(dp(18),dp(4),dp(18),dp(14));root.addView(widget,wp);
 LinearLayout quick=row();quick.setPadding(dp(12),dp(4),dp(12),dp(4));String[] names={"Aplicaciones","Temas","Ajustes","Buscar"};String[] glyph={"▦","◉","⚙","⌕"};for(int i=0;i<4;i++){final int ix=i;LinearLayout item=col();item.setGravity(Gravity.CENTER);TextView icon=tx(glyph[i],25,accent,true);icon.setGravity(17);item.addView(icon);TextView cap=tx(names[i],11,fg,false);cap.setGravity(17);item.addView(cap);item.setOnClickListener(v->{if(ix==0||ix==3)drawer("");else if(ix==1)startActivity(new Intent(this,ThemesActivity.class));else startActivity(new Intent(this,SettingsActivity.class));});quick.addView(item,new LinearLayout.LayoutParams(0,-2,1));}root.addView(quick);
 TextView title=tx("Tus aplicaciones",20,fg,true);title.setPadding(dp(22),dp(17),dp(22),dp(9));root.addView(title);
 LinearLayout apps=row();apps.setPadding(dp(12),dp(4),dp(12),dp(4));String[] labels={"Teléfono","Mensajes","Cámara","Fotos"};String[] glyphs={"☎","✉","◉","✿"};int[] cs={0xFF53B66B,0xFF559CF4,0xFF8B8C99,0xFFF2A34A};for(int i=0;i<4;i++){LinearLayout item=col();item.setGravity(Gravity.CENTER);TextView ic=tx(glyphs[i],24,Color.WHITE,true);ic.setGravity(17);ic.setBackground(shape(cs[i],18));item.addView(ic,new LinearLayout.LayoutParams(dp(52),dp(52)));TextView lab=tx(labels[i],11,fg,false);lab.setGravity(17);lab.setPadding(0,dp(5),0,0);item.addView(lab);apps.addView(item,new LinearLayout.LayoutParams(0,-2,1));}root.addView(apps);
 TextView all=chip("Ver todas las aplicaciones  ↑",()->drawer(""));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.setMargins(dp(20),dp(17),dp(20),dp(12));root.addView(all,ap);
 View spacer=new View(this);root.addView(spacer,new LinearLayout.LayoutParams(1,0,1));TextView dock=tx("●       ●       ●       ●       ●",14,muted,true);dock.setGravity(17);dock.setPadding(10,dp(12),10,dp(18));root.addView(dock);
 }
 void drawer(String q){drawer=true;base();LinearLayout head=row();head.setPadding(dp(20),dp(22),dp(20),dp(12));head.addView(tx("Aplicaciones",27,fg,true),new LinearLayout.LayoutParams(0,-2,1));TextView close=tx("×",30,fg,false);close.setOnClickListener(v->home());head.addView(close);root.addView(head);
 search=new EditText(this);search.setSingleLine(true);search.setTextSize(15);search.setHint("Buscar aplicaciones");search.setHintTextColor(muted);search.setTextColor(fg);search.setBackground(shape(card,25));search.setPadding(dp(18),dp(4),dp(18),dp(4));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(50));sp.setMargins(dp(18),dp(3),dp(18),dp(15));root.addView(search,sp);search.setText(q);
 ScrollView scroll=new ScrollView(this);LinearLayout grid=col();grid.setPadding(dp(12),dp(4),dp(12),dp(20));scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 Runnable fill=()->{grid.removeAllViews();ArrayList<ResolveInfo> list=new ArrayList<>();Intent in=new Intent(Intent.ACTION_MAIN,null);in.addCategory(Intent.CATEGORY_LAUNCHER);for(ResolveInfo r:getPackageManager().queryIntentActivities(in,0)){if(r.activityInfo.packageName.equals(getPackageName()))continue;String n=r.loadLabel(getPackageManager()).toString();if(n.toLowerCase(Locale.ROOT).contains(search.getText().toString().toLowerCase(Locale.ROOT)))list.add(r);}Collections.sort(list,(a,b)->a.loadLabel(getPackageManager()).toString().compareToIgnoreCase(b.loadLabel(getPackageManager()).toString()));for(int i=0;i<list.size();i+=4){LinearLayout rr=row();for(int j=i;j<Math.min(i+4,list.size());j++){ResolveInfo r=list.get(j);LinearLayout item=col();item.setGravity(Gravity.CENTER);ImageView icon=new ImageView(this);icon.setImageDrawable(r.loadIcon(getPackageManager()));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(48),dp(48));ip.setMargins(0,dp(6),0,dp(4));item.addView(icon,ip);TextView label=tx(r.loadLabel(getPackageManager()).toString(),11,fg,false);label.setGravity(17);label.setMaxLines(2);item.addView(label);item.setOnClickListener(v->{Intent launch=getPackageManager().getLaunchIntentForPackage(r.activityInfo.packageName);if(launch!=null)startActivity(launch);});rr.addView(item,new LinearLayout.LayoutParams(0,dp(94),1));}grid.addView(rr);}};
 search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){fill.run();}public void afterTextChanged(android.text.Editable e){}});fill.run();
 }
 @Override public void onBackPressed(){if(drawer)home();else super.onBackPressed();}
}
